// Convert input polygons to CGAL polygons
internal::Polygon_2 cgalP1, cgalP2;
for (const auto& p : P1.vectorPoints()) {
    cgalP1.push_back(internal::Point_2(p.x(), p.y()));
}
for (const auto& p : P2.vectorPoints()) {
    cgalP2.push_back(internal::Point_2(p.x(), p.y()));
}

// Compute union using CGAL
internal::Pwh_list_2 unionResult;
CGAL::join(cgalP1, cgalP2, std::back_inserter(unionResult));

// Convert result back to our format
std::vector<PolygonWithHoles2d> result;
for (const auto& pwh : unionResult) {
    PolygonWithHoles2d polyWithHoles;

    // Convert outer boundary
    Polygon2d outer;
    for (const auto& p : pwh.outer_boundary()) {
        double x, y;
        internal::getCoordinates(p, x, y);
        outer.pushBack(Point2d(x, y));
    }
    polyWithHoles.setOuterPolygon(outer);

    // Convert holes
    for (auto holeIt = pwh.holes_begin(); holeIt != pwh.holes_end(); ++holeIt) {
        Polygon2d hole;
        for (const auto& p : *holeIt) {
            double x, y;
            internal::getCoordinates(p, x, y);
            hole.pushBack(Point2d(x, y));
        }
        polyWithHoles.addHole(hole);
    }

    result.push_back(polyWithHoles);
}

return result;

